strong><span>{@link FFI::__BIGGEST_ALIGNMENT__}</span></strong></dt>     <dd>      <span class="simpara"></span>     </dd>       </dl>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link FFI::addr} — Creates an unmanaged pointer to C data</li><li>{@link FFI::alignof} — Gets the alignment</li><li>{@link FFI::arrayType} — Dynamically constructs a new C array type</li><li>{@link FFI::cast} — Performs a C type cast</li><li>{@link FFI::cdef} — Creates a new FFI object</li><li>{@link FFI::free} — Releases an unmanaged data structure</li><li>{@link FFI::isNull} — Checks whether a FFI\CData is a null pointer</li><li>{@link FFI::load} — Loads C declarations from a C header file</li><li>{@link FFI::memcmp} — Compares memory areas</li><li>{@link FFI::memcpy} — Copies one memory area to another</li><li>{@link FFI::memset} — Fills a memory area</li><li>{@link FFI::new} — Creates a C data structure</li><li>{@link FFI::scope} — Instantiates an FFI object with C declarations parsed during preloading</li><li>{@link FFI::sizeof} — Gets the size of C data or types</li><li>{@link FFI::string} — Creates a PHP string from a memory area</li><li>{@link FFI::type} — Creates an FFI\CType object from a C declaration</li><li>{@link FFI::typeof} — Gets the FFI\CType of FFI\CData</li></ul></div>
 * 
     * FFI class provides access to a simple way to call native functions,
     * access native variables and create/access data structures defined
     * in the C language.
     *
     * @since 7.4
     */
    final class FFI
    {
        public const int __BIGGEST_ALIGNMENT__ = 8;

        /**
 * <div id="ffi.cdef" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::cdef</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::cdef</span> — <span class="dc-title">Creates a new FFI object</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.cdef-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::cdef</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$code</span><span class="initializer"> = ""</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$lib</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi.php" class="type FFI" style="color:#EAB766">FFI</a></span></div>  <p class="simpara">   Creates a new FFI object.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.cdef-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">code</span></dt>    <dd>     <span class="simpara">      A string containing a sequence of declarations in regular C language      (types, structures, functions, variables, etc). Actually, this string may      be copy-pasted from C header files.     </span>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:       <span class="simpara">       C preprocessor directives are not supported, i.e. <span class="code">#include</span>,       <span class="code">#define</span> and CPP macros do not work.      </span>     </p></blockquote>    </dd>          <dt><span class="parameter" style="color:#3A95FF">lib</span></dt>    <dd>     <span class="simpara">      The name of a shared library file, to be loaded and linked with the      definitions.     </span>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:       <span class="simpara">       If <span class="parameter" style="color:#3A95FF">lib</span> is omitted or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>, platforms supporting <span class="literal">RTLD_DEFAULT</span>       attempt to lookup symbols declared in <span class="parameter" style="color:#3A95FF">code</span> in the normal global       scope. Other systems will fail to resolve these symbols.      </span>     </p></blockquote>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.cdef-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the freshly created <span class="classname"><a href="https://php.net/manual/zh/class.ffi.php" class="classname">FFI</a></span> object.  </p> </div> <div class="refsect1 changelog" id="refsect1-ffi.cdef-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.3.0</td>      <td>       C functions returning <span class="literal">void</span> return a PHP <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">null</a></span>       instead of <var class="varname">FFI\CType::TYPE_VOID</var>.      </td>     </tr>     <tr>      <td>8.0.0</td>      <td>       <span class="parameter" style="color:#3A95FF">lib</span> is nullable now.      </td>     </tr>    </tbody>     </table> </div></div>
 * 
         * The method creates a binding on the existing C function.
         *
         * All variables and functions defined by first arguments are bound
         * to corresponding native symbols in a DSO library and then may be
         * accessed as FFI object methods and properties. C types of argument,
         * return value, and variables are automatically converted to/from PHP
         * types (if possible). Otherwise, they are wrapped in a special CData
         * proxy object and may be accessed by elements.
         *
         * @link https://www.php.net/manual/en/ffi.cdef.php
         *
         * @param string $code A string containing a sequence of declarations
         *        in regular C language (types, structures, functions, variables,
         *        etc). Actually, this string may be copy-pasted from C header files.
         *
         *        Note: C preprocessor directives are not supported, i.e.
         *              `#include`, `#define` and CPP macros do not work.
         * @param string|null $lib The name of a shared library file, to be
         *        loaded and linked with the definitions.
         *
         *        Note: If lib is omitted or {@see null}, platforms supporting
         *              RTLD_DEFAULT attempt to lookup symbols declared in code
         *              in the normal global scope. Other systems will fail to
         *              resolve these symbols.
         *
         * @return FFI Returns the freshly created FFI object.
         * @throws ParserException
         */
        public static function cdef(string $code = '', ?string $lib = null): FFI {}

        /**
 * <div id="ffi.load" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::load</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::load</span> — <span class="dc-title">Loads C declarations from a C header file</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.load-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::load</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$filename</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi.php" class="type FFI" style="color:#EAB766">FFI</a></span></span></div>  <p class="simpara">   Loads C declarations from a C header file. It is possible to specify shared libraries that should be loaded,   using special <span class="literal">FFI_LIB</span> defines in the loaded C header file.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.load-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">filename</span></dt>    <dd>     <span class="simpara">      The name of a C header file.     </span>     <span class="simpara">      C preprocessor directives are not supported, i.e. <span class="literal">#include</span>,      <span class="literal">#define</span> and CPP macros do not work, except for special cases      listed below.     </span>     <span class="simpara">      The header file <em>should</em> contain a <span class="literal">#define</span> statement for the      <span class="literal">FFI_SCOPE</span> variable, e.g.: <span class="code">#define FFI_SCOPE "MYLIB"</span>.      Refer to the <a href="https://php.net/manual/zh/class.ffi.php#ffi.intro" class="link">class introduction</a> for details.     </span>     <span class="simpara">      The header file <em>may</em> contain a <span class="literal">#define</span> statement for the      <span class="literal">FFI_LIB</span> variable to specify the library it exposes. If it is      a system library only the file name is required, e.g.: <span class="code">#define FFI_LIB      "libc.so.6"</span>.  If it is a custom library, a relative path is required,      e.g.: <span class="code">#define FFI_LIB "./mylib.so"</span>.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.load-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the freshly created <span class="classname"><a href="https://php.net/manual/zh/class.ffi.php" class="classname">FFI</a></span> object, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> on failure.  </p> </div> <div class="refsect1 changelog" id="refsect1-ffi.load-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.3.0</td>      <td>       <span class="methodname" style="color:#CC7832"><strong>FFI::load()</strong></span> is now allowed in       <a href="https://php.net/manual/zh/opcache.preloading.php" class="link">preload scripts</a> when the       current system user is the same as the one defined in the       <span class="literal">opcache.preload_user</span> configuration directive.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 seealso" id="refsect1-ffi.load-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link FFI::scope()} - Instantiates an FFI object with C declarations parsed during preloading</span></li>  </ul> </div></div>
 * 
         * Instead of embedding of a long C definition into a PHP string
         * and creating FFI through {@see FFI::cdef()}, it's possible to
         * separate it into a C header file. Note that C preprocessor
         * directives (e.g., `#define` or `#ifdef`) are not supported. And
         * only a couple of special macros may be used, especially for FFI.
         *
         * ```c
         * #define FFI_LIB "libc.so.6"
         *
         * int printf(const char *format, ...);
         * ```
         *
         * Here, `FFI_LIB` specifies that the given library should be loaded.
         *
         * ```php
         * $ffi = FFI::load(__DIR__ . "/printf.h");
         * $ffi->printf("Hello world!\n");
         * ```
         *
         * @link https://www.php.net/manual/en/ffi.load.php
         *
         * @param string $filename The name of a C header file. C preprocessor
         *        directives are not supported, i.e. `#include`, `#define` and
         *        CPP macros do not work, except for special cases listed below.
         *        The header file should contain a #define statement for the
         *        `FFI_SCOPE` variable, e.g.: `#define FFI_SCOPE "MYLIB"`. Refer
         *        to the class introduction for details. The header file may
         *        contain a `#define` statement for the `FFI_LIB` variable to
         *        specify the library it exposes. If it is a system library only
         *        the file name is required, e.g.: `#define FFI_LIB "libc.so.6"`.
         *        If it is a custom library, a relative path is required,
         *        e.g.: `#define FFI_LIB "./mylib.so"`.
         *
         * @return FFI|null Returns the freshly created {@see FFI} object,
         *         or {@see null} on failure.
         */
        public static function load(string $filename): ?FFI {}

        /**
 * <div id="ffi.scope" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::scope</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::scope</span> — <span class="dc-title">Instantiates an FFI object with C declarations parsed during preloading</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.scope-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::scope</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$name</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi.php" class="type FFI" style="color:#EAB766">FFI</a></span></div>  <p class="simpara">   Instantiates an FFI object with C declarations parsed during preloading.  </p>  <p class="simpara">   The <span class="methodname" style="color:#CC7832"><strong>FFI::scope()</strong></span> method is safe to call multiple times for the same scope. Multiple references to the   same scope may be loaded at the same time.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.scope-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">name</span></dt>    <dd>     <span class="simpara">      The scope name defined by a special <span class="literal">FFI_SCOPE</span> define.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.scope-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the freshly created <span class="classname"><a href="https://php.net/manual/zh/class.ffi.php" class="classname">FFI</a></span> object.  </p> </div> <div class="refsect1 seealso" id="refsect1-ffi.scope-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link FFI::load()} - Loads C declarations from a C header file</span></li>  </ul> </div></div>
 * 
         * FFI definition parsing and shared library loading may take
         * significant time. It's not useful to do it on each HTTP request in
         * the WEB environment. However, it's possible to preload FFI
         * definitions and libraries at php startup, and instantiate FFI objects
         * when necessary. Header files may be extended with `FFI_SCOPE` define
         * (default preloading scope is "C"). This name is going to be
         * used as {@see FFI::scope()} argument. It's possible to preload a few
         * files into a single scope.
         *
         * ```c
         * #define FFI_LIB "libc.so.6"
         * #define FFI_SCOPE "libc"
         *
         * int printf(const char *format, ...);
         * ```
         *
         * These files are loaded through the same FFI::load() load function,
         * executed from a file loaded by `opcache.preload` in the `php.ini`
         * directive.
         *
         * ```c
         * ffi.preload=/etc/php/ffi/printf.h
         * ```
         *
         * Finally, FFI::scope() instantiates an FFI object that implements
         * all C definitions from the given scope.
         *
         * ```php
         * $ffi = FFI::scope("libc");
         * $ffi->printf("Hello world!\n");
         * ```
         *
         * @link https://www.php.net/manual/en/ffi.scope.php
         *
         * @param string $name The scope name defined by a special `FFI_SCOPE` define.
         *
         * @return FFI Returns the freshly created {@see FFI} object.
         */
        public static function scope(string $name): FFI {}

        /**
 * <div id="ffi.new" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::new</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::new</span> — <span class="dc-title">Creates a C data structure</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.new-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::new</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="type FFI\CType" style="color:#EAB766">FFI\CType</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$type</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span> <span class="parameter" style="color:#3A95FF">\$owned</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong></span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span> <span class="parameter" style="color:#3A95FF">\$persistent</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span></span></div>  <p class="simpara">   Creates a native data structure of the given C type.   Any type declared for the instance is allowed.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.new-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">type</span></dt>    <dd>     <span class="simpara">      <span class="parameter" style="color:#3A95FF">type</span> is a valid C declaration as <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>, or an      instance of <span class="classname"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="classname">FFI\CType</a></span> which has already been created.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">owned</span></dt>    <dd>     <span class="simpara">      Whether to create owned (i.e. managed) or unmanaged data. Managed data lives together      with the returned <span class="classname"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="classname">FFI\CData</a></span> object, and is released when the      last reference to that object is released by regular PHP reference counting or GC.      Unmanaged data should be released by calling <span class="methodname" style="color:#CC7832">{@link FFI::free()}</span>,      when no longer needed.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">persistent</span></dt>    <dd>     <span class="simpara">      Whether to allocate the C data structure permanently on the system heap (using      <span class="function"><strong style="color:#CC7832">malloc()</strong></span>), or on the PHP request heap (using <span class="function"><strong style="color:#CC7832">emalloc()</strong></span>).     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.new-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the freshly created <span class="classname"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="classname">FFI\CData</a></span> object,   or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> on failure.  </p> </div> <div class="refsect1 changelog" id="refsect1-ffi.new-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.3.0</td>      <td>       Calling <span class="methodname" style="color:#CC7832"><strong>FFI::new()</strong></span> statically is now deprecated.      </td>     </tr>    </tbody>     </table> </div></div>
 * 
         * Method that creates an arbitrary C structure.
         *
         * Creates a native data structure of the given C type. Any type
         * declared for the instance is allowed.
         *
         * Note: Calling {@see FFI::new()} statically is deprecated since PHP 8.3.
         *
         * @link https://www.php.net/manual/en/ffi.new.php
         *
         * @param string|CType $type is a valid C declaration as {@see string},
         *        or an instance of {@see FFI\CType} which has already been created.
         * @param bool $owned Whether to create owned (i.e. managed) or unmanaged
         *        data. Managed data lives together with the returned
         *        {@see FFI\CData} object, and is released when the last
         *        reference to that object is released by regular PHP
         *        reference counting or GC. Unmanaged data should be released
         *        by calling {@see FFI::free()}, when no longer needed.
         * @param bool $persistent Whether to allocate the C data structure
         *        permanently on the system heap (using `malloc()`), or on
         *        the PHP request heap (using `emalloc()`).
         *
         * @return CData|null Returns the freshly created {@see FFI\CData}
         *         object, or {@see null} on failure for PHP versions prior to 8.4.
         * @throws ParserException
         */
        #[LanguageLevelTypeAware(['8.4' => '\FFI\CData'], default: '\FFI\CData|null')]
        public function new(CType|string $type, bool $owned = true, bool $persistent = false) {}

        /**
 * <div id="ffi.free" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::free</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::free</span> — <span class="dc-title">Releases an unmanaged data structure</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.free-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::free</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$ptr</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Manually releases a previously created unmanaged data structure.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.free-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">ptr</span></dt>    <dd>     <span class="simpara">      The handle of the unmanaged pointer to a C data structure.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.free-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div></div>
 * 
         * Manually removes previously created "not-owned" data structure.
         *
         * @link https://www.php.net/manual/en/ffi.free.php
         *
         * @param CData $ptr The handle of the unmanaged pointer to a C data structure.
         */
        public static function free(CData $ptr): void {}

        /**
 * <div id="ffi.cast" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::cast</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::cast</span> — <span class="dc-title">Performs a C type cast</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.cast-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::cast</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="type FFI\CType" style="color:#EAB766">FFI\CType</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$type</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">null</a></span></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$ptr</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span></span></div>  <p class="simpara">   <span class="methodname" style="color:#CC7832"><strong>FFI::cast()</strong></span> creates a new <span class="classname"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="classname">FFI\CData</a></span>   object, that references the same C data structure, but is associated with a different type.   The resulting object does not own the C data, and the source <span class="parameter" style="color:#3A95FF">ptr</span>   must survive the result. The C type may be specified as a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> with any   valid C type declaration or as <span class="classname"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="classname">FFI\CType</a></span> object, created before.   Any type declared for the instance is allowed.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.cast-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">type</span></dt>    <dd>     <span class="simpara">      A valid C declaration as <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>, or an instance of <span class="classname"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="classname">FFI\CType</a></span>      which has already been created.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">ptr</span></dt>    <dd>     <span class="simpara">      The handle of the pointer to a C data structure.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.cast-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the freshly created <span class="classname"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="classname">FFI\CData</a></span> object.  </p> </div> <div class="refsect1 changelog" id="refsect1-ffi.cast-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.3.0</td>      <td>       Calling <span class="methodname" style="color:#CC7832"><strong>FFI::cast()</strong></span> statically is now deprecated.      </td>     </tr>    </tbody>     </table> </div></div>
 * 
         * Creates a new {@see FFI\CData} object, that references the same
         * C data structure, but is associated with a different type. The
         * resulting object does not own the C data, and the source ptr must
         * survive the result. The C type may be specified as a {@see string}
         * with any valid C type declaration or as {@see FFI\CType} object,
         * created before. Any type declared for the instance is allowed.
         *
         * Note: Calling {@see FFI::cast()} statically is deprecated since PHP 8.3.
         *
         * ```php
         * $ffi = FFI::cdef();
         *
         * $int32Value = $ffi->new('int32_t');
         * $int16Array = $ffi->cast('int16_t[2]', $int32Value);
         * ```
         *
         * @link https://www.php.net/manual/en/ffi.free.php
         *
         * @param CType|string $type A valid C declaration as {@see string}, or
         *       an instance of {@see FFI\CType} which has already been created.
         * @param CData|int|float|bool|null $ptr The handle of the pointer
         *        to a C data structure.
         *
         * @return CData|null Returns the freshly created {@see FFI\CData} object,
         * or {@see null} on failure for PHP versions prior to 8.4.
         */
        #[LanguageLevelTypeAware(['8.4' => '\FFI\CData'], default: '\FFI\CData|null')]
        public function cast(CType|string $type, $ptr) {}

        /**
 * <div id="ffi.type" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::type</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::type</span> — <span class="dc-title">Creates an FFI\CType object from a C declaration</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.type-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::type</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$type</span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="type FFI\CType" style="color:#EAB766">FFI\CType</a></span></span></div>  <p class="simpara">   This function creates and returns a <span class="classname"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="classname">FFI\CType</a></span> object for the   given <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> containing a C type declaration.   Any type declared for the instance is allowed.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.type-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">type</span></dt>    <dd>     <span class="simpara">      A valid C declaration as <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.type-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the freshly created <span class="classname"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="classname">FFI\CType</a></span> object,   or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> on failure.  </p> </div> <div class="refsect1 changelog" id="refsect1-ffi.type-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.3.0</td>      <td>       Calling <span class="methodname" style="color:#CC7832"><strong>FFI::type()</strong></span> statically is now deprecated.      </td>     </tr>    </tbody>     </table> </div></div>
 * 
         * This function creates and returns a {@see FFI\CType} object for
         * the given string containing a C type declaration. Any type
         * declared for the instance is allowed.
         *
         * Note: Calling {@see FFI::type()} statically is deprecated since PHP 8.3.
         *
         * ```php
         * $ffi = FFI::cdef();
         *
         * $type = $ffi->type('int[2][3]');
         * ```
         *
         * @link https://www.php.net/manual/en/ffi.type.php
         *
         * @param string $type A valid C declaration as {@see string}.
         * @return CType|null Returns the freshly created {@see FFI\CType}
         *         object, or {@see null} on failure for PHP versions prior to 8.4.
         */
        #[LanguageLevelTypeAware(['8.4' => '\FFI\CType'], default: '\FFI\CType|null')]
        public function type(string $type) {}

        /**
 * <div id="ffi.typeof" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::typeof</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::typeof</span> — <span class="dc-title">Gets the FFI\CType of FFI\CData</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.typeof-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::typeof</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$ptr</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="type FFI\CType" style="color:#EAB766">FFI\CType</a></span></div>  <p class="simpara">   Gets the <span class="classname"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="classname">FFI\CType</a></span> object representing the type of the given   <span class="classname"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="classname">FFI\CData</a></span> object.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.typeof-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">ptr</span></dt>    <dd>     <span class="simpara">      The handle of the pointer to a C data structure.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.typeof-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the <span class="classname"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="classname">FFI\CType</a></span> object representing the type of the given   <span class="classname"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="classname">FFI\CData</a></span> object.  </p> </div></div>
