        /**
 * <div id="ffi.arraytype" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::arrayType</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::arrayType</span> — <span class="dc-title">Dynamically constructs a new C array type</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.arraytype-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::arrayType</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="type FFI\CType" style="color:#EAB766">FFI\CType</a></span> <span class="parameter" style="color:#3A95FF">\$type</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$dimensions</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="type FFI\CType" style="color:#EAB766">FFI\CType</a></span></div>  <p class="para rdfs-comment">   Dynamically constructs a new C array type with elements of type defined by <span class="parameter" style="color:#3A95FF">type</span>,   and dimensions specified by <span class="parameter" style="color:#3A95FF">dimensions</span>. In the following example <span class="code">\$t1</span>   and <span class="code">\$t2</span> are equivalent array types:   </p><div class="informalexample">    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$t1 </span><span style="color: #007700">= </span><span style="color: #9876AA">FFI</span><span style="color: #007700">::</span><span style="color: #9876AA">type</span><span style="color: #007700">(</span><span style="color: #DD0000">"int[2][3]"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$t2 </span><span style="color: #007700">= </span><span style="color: #9876AA">FFI</span><span style="color: #007700">::</span><span style="color: #9876AA">arrayType</span><span style="color: #007700">(</span><span style="color: #9876AA">FFI</span><span style="color: #007700">::</span><span style="color: #9876AA">type</span><span style="color: #007700">(</span><span style="color: #DD0000">"int"</span><span style="color: #007700">), [</span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   </div> <div class="refsect1 parameters" id="refsect1-ffi.arraytype-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">type</span></dt>    <dd>     <span class="simpara">      A valid C declaration as <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>, or an instance of <span class="classname"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="classname">FFI\CType</a></span>      which has already been created.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">dimensions</span></dt>    <dd>     <span class="simpara">      The dimensions of the type as <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.arraytype-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the freshly created <span class="classname"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="classname">FFI\CType</a></span> object.  </p> </div></div>
 * 
         * Constructs a new C array type with elements of $type and
         * dimensions specified by `$dimensions`.
         *
         * ```php
         * $ffi = FFI::cdef();
         *
         * $t1 = $ffi->type('int[2][3]');
         * $t2 = FFI::arrayType($ffi->type('int'), [2, 3]);
         * ```
         *
         * @link https://www.php.net/manual/en/ffi.arraytype.php
         *
         * @param CType $type A valid C declaration as string, or an instance
         *        of {@see FFI\CType} which has already been created.
         * @param array<array-key, int<0, max>> $dimensions The dimensions of
         *        the type as {@see array}.
         *
         * @return CType Returns the freshly created {@see FFI\CType} object.
         */
        public static function arrayType(CType $type, array $dimensions): CType {}

        /**
 * <div id="ffi.addr" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::addr</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::addr</span> — <span class="dc-title">Creates an unmanaged pointer to C data</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.addr-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::addr</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$ptr</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span></div>  <p class="simpara">   Creates an unmanaged pointer to the C data represented by the given   <span class="classname"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="classname">FFI\CData</a></span>. The source <span class="parameter" style="color:#3A95FF">ptr</span> must survive the   resulting pointer. This function is mainly useful to pass arguments to C functions by pointer.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.addr-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">ptr</span></dt>    <dd>     <span class="simpara">      The handle of the pointer to a C data structure.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.addr-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the freshly created <span class="classname"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="classname">FFI\CData</a></span> object.  </p> </div></div>
 * 
         * Returns a C pointer to the given C data structure. The pointer is
         * not "owned" and won't be free. Anyway, this is a potentially
         * unsafe operation, because the life-time of the returned pointer
         * may be longer than the life-time of the source object, and this may
         * cause dangling pointer dereference (like in regular C).
         *
         * @link https://www.php.net/manual/en/ffi.addr.php
         *
         * @param CData $ptr The handle of the pointer to a C data structure.
         *
         * @return CData Returns the freshly created {@see FFI\CData} object.
         * @meta
         */
        public static function addr(CData $ptr): CData {}

        /**
 * <div id="ffi.sizeof" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::sizeof</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::sizeof</span> — <span class="dc-title">Gets the size of C data or types</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.sizeof-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::sizeof</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="type FFI\CType" style="color:#EAB766">FFI\CType</a></span></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$ptr</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="simpara">   Returns the size of the given <span class="classname"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="classname">FFI\CData</a></span> or   <span class="classname"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="classname">FFI\CType</a></span> object.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.sizeof-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">ptr</span></dt>    <dd>     <span class="simpara">      The handle of the C data or type.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.sizeof-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The size of the memory area pointed at by <span class="parameter" style="color:#3A95FF">ptr</span>.  </p> </div></div>
 * 
         * Returns the size of a C data type of the given {@see FFI\CData}
         * or {@see FFI\CType}.
         *
         * @link https://www.php.net/manual/en/ffi.sizeof.php
         *
         * @param CData|CType $ptr The handle of the C data or type.
         *
         * @return int<0, max> The size of the memory area pointed at by ptr.
         */
        public static function sizeof(CData|CType $ptr): int {}

        /**
 * <div id="ffi.alignof" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::alignof</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::alignof</span> — <span class="dc-title">Gets the alignment</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.alignof-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::alignof</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="type FFI\CType" style="color:#EAB766">FFI\CType</a></span></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$ptr</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="simpara">   Gets the alignment of the given <span class="classname"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="classname">FFI\CData</a></span> or   <span class="classname"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="classname">FFI\CType</a></span> object.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.alignof-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">ptr</span></dt>    <dd>     <span class="simpara">      The handle of the C data or type.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.alignof-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the alignment of the given <span class="classname"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="classname">FFI\CData</a></span> or   <span class="classname"><a href="https://php.net/manual/zh/class.ffi-ctype.php" class="classname">FFI\CType</a></span> object.  </p> </div></div>
 * 
         * Returns the size of a C data type of the given {@see FFI\CData} or
         * {@see FFI\CType}.
         *
         * @link https://www.php.net/manual/en/ffi.alignof.php
         *
         * @param CData|CType $ptr The handle of the C data or type.
         *
         * @return int<0, max> Returns the alignment of the given
         *         {@see FFI\CData} or {@see FFI\CType} object.
         */
        public static function alignof(CData|CType $ptr): int {}

        /**
 * <div id="ffi.memcpy" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::memcpy</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::memcpy</span> — <span class="dc-title">Copies one memory area to another</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.memcpy-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::memcpy</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$to</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$from</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$size</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Copies <span class="parameter" style="color:#3A95FF">size</span> bytes from the memory area <span class="parameter" style="color:#3A95FF">from</span>   to the memory area <span class="parameter" style="color:#3A95FF">to</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.memcpy-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">to</span></dt>    <dd>     <span class="simpara">      The start of the memory area to copy to.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">from</span></dt>    <dd>     <span class="simpara">      The start of the memory area to copy from.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">size</span></dt>    <dd>     <span class="simpara">      The number of bytes to copy.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.memcpy-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div></div>
 * 
         * Copies `$size` bytes from the memory area `$from` to the memory area `$to`.
         *
         * @link https://www.php.net/manual/en/ffi.memcpy.php
         *
         * @param CData $to The start of the memory area to copy to.
         * @param CData|string $from The start of the memory area to copy from.
         * @param int<0, max> $size The number of bytes to copy.
         */
        public static function memcpy(CData $to, $from, int $size): void {}

        /**
 * <div id="ffi.memcmp" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::memcmp</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::memcmp</span> — <span class="dc-title">Compares memory areas</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.memcmp-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::memcmp</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$ptr1</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$ptr2</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$size</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="simpara">   Compares <span class="parameter" style="color:#3A95FF">size</span> bytes from the memory areas <span class="parameter" style="color:#3A95FF">ptr1</span> and   <span class="parameter" style="color:#3A95FF">ptr2</span>. Both <span class="parameter" style="color:#3A95FF">ptr1</span> and <span class="parameter" style="color:#3A95FF">ptr2</span>   can be any native data structures (<span class="classname"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="classname">FFI\CData</a></span>) or PHP   <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>s.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.memcmp-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">ptr1</span></dt>    <dd>     <span class="simpara">      The start of one memory area.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">ptr2</span></dt>    <dd>     <span class="simpara">      The start of another memory area.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">size</span></dt>    <dd>     <span class="simpara">      The number of bytes to compare.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.memcmp-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a value less than <span class="literal">0</span> if the contents of the memory area starting at <span class="parameter" style="color:#3A95FF">ptr1</span>   are considered less than the contents of the memory area starting at <span class="parameter" style="color:#3A95FF">ptr2</span>,   a value greater than <span class="literal">0</span> if the contents of the first memory area are considered greater than the second,   and <span class="literal">0</span> if they are equal.  </p> </div></div>
 * 
         * Compares `$size` bytes from the memory areas `$ptr1` and `$ptr2`.
         * Both `$ptr1` and `$ptr2` can be any native data structures
         * ({@see FFI\CData}) or PHP strings.
         *
         * @link https://www.php.net/manual/en/ffi.memcmp.php
         *
         * @param CData|string $ptr1 The start of one memory area.
         * @param CData|string $ptr2 The start of another memory area.
         * @param int<0, max> $size The number of bytes to compare.
         *
         * @return int<-1, 1> Returns a value less than 0 if the contents of the
         *         memory area starting at `$ptr1` are considered less than the
         *         contents of the memory area starting at `$ptr2`, a value
         *         greater than 0 if the contents of the first memory area are
         *         considered greater than the second, and 0 if they are equal.
         */
        public static function memcmp($ptr1, $ptr2, int $size): int {}

        /**
 * <div id="ffi.memset" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::memset</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::memset</span> — <span class="dc-title">Fills a memory area</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.memset-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::memset</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$ptr</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$size</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Fills <span class="parameter" style="color:#3A95FF">size</span> bytes of the memory area pointed to by   <span class="parameter" style="color:#3A95FF">ptr</span> with the given byte <span class="parameter" style="color:#3A95FF">value</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.memset-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">ptr</span></dt>    <dd>     <span class="simpara">      The start of the memory area to fill.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">value</span></dt>    <dd>     <span class="simpara">      The byte to fill with.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">size</span></dt>    <dd>     <span class="simpara">      The number of bytes to fill.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.memset-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div></div>
 * 
         * Fills `$size` bytes of the memory area pointed to by `$ptr` with the
         * given byte `$value`.
         *
         * @link https://www.php.net/manual/en/ffi.memset.php
         *
         * @param CData $ptr The start of the memory area to fill.
         * @param int $value The byte to fill with.
         * @param int<0, max> $size The number of bytes to fill.
         */
        public static function memset(CData $ptr, int $value, int $size): void {}

        /**
 * <div id="ffi.string" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::string</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::string</span> — <span class="dc-title">Creates a PHP string from a memory area</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.string-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::string</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$ptr</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></span> <span class="parameter" style="color:#3A95FF">\$size</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Creates a PHP <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> from <span class="parameter" style="color:#3A95FF">size</span> bytes of the memory area   pointed to by <span class="parameter" style="color:#3A95FF">ptr</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.string-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">ptr</span></dt>    <dd>     <span class="simpara">      The start of the memory area from which to create a <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">size</span></dt>    <dd>     <span class="simpara">      The number of bytes to copy to the <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>.      If <span class="parameter" style="color:#3A95FF">size</span> is omitted or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>, <span class="parameter" style="color:#3A95FF">ptr</span> must be a zero terminated      array of C <span class="literal">char</span>.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.string-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The freshly created PHP <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>.  </p> </div> <div class="refsect1 changelog" id="refsect1-ffi.string-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.0.0</td>      <td>       <span class="parameter" style="color:#3A95FF">size</span> is nullable now; previously, its default was       <span class="literal">0</span>.      </td>     </tr>    </tbody>     </table> </div></div>
 * 
         * Creates a PHP string from `$size` bytes of the memory area pointed
         * by `$ptr`. If size is omitted, `$ptr` must be a zero-terminated
         * array of C chars.
         *
         * @link https://www.php.net/manual/en/ffi.string.php
         *
         * @param CData $ptr The start of the memory area from which to
         *        create a PHP {@see string}.
         * @param int<0, max>|null $size The number of bytes to copy to the
         *        PHP {@see string}. If `$size` is omitted or {@see null},
         *        `$ptr` must be a zero-terminated ("\0") array of C char.
         *
         * @return string The freshly created PHP {@see string}.
         */
        public static function string(CData $ptr, ?int $size = null): string {}

        /**
 * <div id="ffi.isnull" class="refentry"> <div class="refnamediv">  <h1 class="refname">FFI::isNull</h1>  <p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p><p class="refpurpose"><span class="refname">FFI::isNull</span> — <span class="dc-title">Checks whether a FFI\CData is a null pointer</span></p> </div> <div class="refsect1 description" id="refsect1-ffi.isnull-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">static</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>FFI::isNull</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="type FFI\CData" style="color:#EAB766">FFI\CData</a></span> <span class="parameter reference" style="color:#3A95FF">&amp;\$ptr</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">   Checks whether a FFI\CData is a null pointer.  </p> </div> <div class="refsect1 parameters" id="refsect1-ffi.isnull-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">ptr</span></dt>    <dd>     <span class="simpara">      The handle of the pointer to a C data structure.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ffi.isnull-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns whether a <span class="classname"><a href="https://php.net/manual/zh/class.ffi-cdata.php" class="classname">FFI\CData</a></span> is a null pointer.  </p> </div></div>
