    final class ParserException extends Exception {}

    /**
 * <div id="class.ffi-cdata" class="reference"> <h1 class="title">C Data Handles</h1>  <div class="partintro"><p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p>  <div class="section" id="ffi-cdata.intro">   <h2 class="title">简介</h2>   <p class="para">    <span class="classname"><strong class="classname">FFI\CData</strong></span> objects can be used in a number of ways as a regular    PHP data:    </p><ul class="itemizedlist">     <li class="listitem">      <span class="simpara">       C data of scalar types can be read and assigned via the <span class="property">\$cdata</span> property, e.g.        <span class="code">\$x = FFI::new('int'); \$x-&gt;cdata = 42;</span>      </span>     </li>     <li class="listitem">      <span class="simpara">       C struct and union fields can be accessed as regular PHP object property, e.g.       <span class="code">\$cdata-&gt;field</span>      </span>     </li>     <li class="listitem">      <span class="simpara">       C array elements can be accessed as regular PHP array elements, e.g.       <span class="code">\$cdata[\$offset]</span>      </span>     </li>     <li class="listitem">      <span class="simpara">       C arrays can be iterated using <a href="https://php.net/manual/zh/control-structures.foreach.php" class="link"><span class="literal">foreach</span></a> statements.      </span>     </li>     <li class="listitem">      <span class="simpara">       C arrays can be used as arguments of <span class="function">{@link count()}</span>.      </span>     </li>     <li class="listitem">      <span class="simpara">       C pointers can be dereferenced as arrays, e.g. <span class="code">\$cdata[0]</span>      </span>     </li>     <li class="listitem">      <span class="simpara">       C pointers can be compared using regular comparison operators (<span class="code">&lt;</span>,       <span class="code">&lt;=</span>, <span class="code">==</span>, <span class="code">!=</span>, <span class="code">&gt;=</span>, <span class="code">&gt;</span>).      </span>     </li>     <li class="listitem">      <span class="simpara">       C pointers can be incremented and decremented using regular <span class="code">+</span>/<span class="code">-</span>/       <span class="code">++</span>/<span class="code">--</span> operations, e.g. <span class="code">\$cdata += 5</span>      </span>     </li>     <li class="listitem">      <span class="simpara">       C pointers can be subtracted from another using regular <span class="code">-</span> operations.      </span>     </li>     <li class="listitem">      <span class="simpara">       C pointers to functions can be called as a regular PHP closure, e.g. <span class="code">\$cdata()</span>      </span>     </li>     <li class="listitem">      <span class="simpara">       Any C data can be duplicated using the <a href="https://php.net/manual/zh/language.oop5.cloning.php" class="link">clone</a>       operator, e.g. <span class="code">\$cdata2 = clone \$cdata;</span>      </span>     </li>     <li class="listitem">      <span class="simpara">       Any C data can be visualized using <span class="function">{@link var_dump()}</span>, <span class="function">{@link print_r()}</span>, etc.      </span>     </li>     <li class="listitem">      <span class="simpara">       <span class="classname"><strong class="classname">FFI\CData</strong></span> can now be assigned to structs and fields as of PHP 8.3.0.      </span>     </li>    </ul>    <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:      <span class="simpara">      Notable limitations are that <span class="classname"><strong class="classname">FFI\CData</strong></span> instances do not support      <span class="function">{@link isset()}</span>, <span class="function">{@link empty()}</span> and <span class="function">{@link unset()}</span>,      and that wrapped C structs and unions do not implement <span class="interfacename"><a href="https://php.net/manual/zh/class.traversable.php" class="interfacename">Traversable</a></span>.     </span>    </p></blockquote>     </div>  <div class="section" id="ffi-cdata.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis"><div class="classsynopsisinfo">    <span class="modifier">namespace</span> <strong class="package">FFI</strong>;</div>    <div class="classsynopsisinfo">           <span class="modifier">final</span>      <span class="modifier">class</span> <strong class="classname"><strong class="classname">CData</strong></strong>      {</div>    }   </div>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>8.3.0</td>       <td>        <span class="classname"><strong class="classname">FFI\CData</strong></span> can now be assigned to structs and fields.       </td>      </tr>     </tbody>       </table>  </div> </div> </div>
 * 
     * Proxy object that provides access to compiled structures.
     *
     * - In the case that {@see CData} is a wrapper over raw C data, it
     *   contains an additional {@see CData::$cdata} property.
     *
     * - In the case that the CData is a wrapper over an arbitrary C structure,
     *   then it allows reading and writing to the fields defined by
     *   this structure.
     *
     * - In the case that CData is a wrapper over an array, it is an
     *   implementation of the {@see \Traversable}, {@see \Countable},
     *   and {@see \ArrayAccess}
     *
     * - In the case when CData is a wrapper over a function pointer, it can
     *   be called.
     *
     * @link https://www.php.net/manual/en/class.ffi-cdata.php
     *
     * @template T of int|float|bool|null|string|CData = null
     *
     * @mixin \Countable
     * @mixin \Traversable<int<0, max>, T>
     * @mixin \ArrayAccess<int<0, max>, T>
     *
     * @property T $cdata
     *
     * @method mixed __get(string $name)
     * @method mixed __set(string $name, mixed $value)
     * @method mixed __invoke(mixed ...$args)
     *
     * @since 7.4
     */
    final class CData
    {
        /**
         * Note that this method does not physically exist and is only required
         * for correct type inference.
         *
         * @param int<0, max> $offset
         */
        private function offsetExists(int $offset) {}

        /**
         * Note that this method does not physically exist and is only required
         * for correct type inference.
         *
         * @param int<0, max> $offset
         * @return T
         */
        private function offsetGet(int $offset): mixed {}

        /**
         * Note that this method does not physically exist and is only required
         * for correct type inference.
         *
         * @param int<0, max> $offset
         * @param T $value
         */
        private function offsetSet(int $offset, mixed $value): void {}

        /**
         * Note that this method does not physically exist and is only required
         * for correct type inference.
         *
         * @param int<0, max> $offset
         */
        private function offsetUnset(int $offset): void {}

        /**
         * Note that this method does not physically exist and is only required
         * for correct type inference.
         *
         * @return int<0, max>
         */
        private function count(): int {}
    }

    /**
 * <div id="class.ffi-ctype" class="reference"> <h1 class="title">C Type Handles</h1>  <div class="partintro"><p class="verinfo">(PHP 7 &gt;= 7.4.0, PHP 8)</p>  <div class="section" id="ffi-ctype.intro">   <h2 class="title">简介</h2>   <p class="simpara">   </p>  </div>  <div class="section" id="ffi-ctype.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis"><div class="classsynopsisinfo">    <span class="modifier">namespace</span> <strong class="package">FFI</strong>;</div>    <div class="classsynopsisinfo">           <span class="modifier">final</span>      <span class="modifier">class</span> <strong class="classname"><strong class="classname">CType</strong></strong>      {</div>     <div class="classsynopsisinfo classsynopsisinfo_comment">// 常量 </div>     <div class="fieldsynopsis">      <span class="modifier">public</span>      <span class="modifier">const</span>      <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>       <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.ffi-ctype.php#ffi-ctype.constants.type-void"><var class="varname">TYPE_VOID</var></a></var>;</div>     <div class="fieldsynopsis"><span class="modifier">public</span>      <span class="modifier">const</span>      <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>       <var class="fieldsynopsis_varname"><a href="https://php.net/manual/zh/class.ffi-ctype.php#ffi-ctype.constants.type-float"><var class="varname">TYPE_FLOAT</var></a></var>;</div>     <div class="fieldsynopsis"><span class="modifier">public</span>      <span class="modifier">const</span>      <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>       <var class="fieldsynopsis_varn